"""Exact 128x32 DMD header checkpoints for the Guns N' Roses US 3.00 ROM.

This bounded adapter matches nonzero pixels in the top ten rows against
visually read, retained exploratory screenshots. It does not infer arbitrary
text. Unknown headers return empty text and the ordinary harness times out.
The rest of the harness, isolated state and raw event capture are unchanged.
"""
from __future__ import annotations

import base64
import sys

import run_pinmame_harness as harness

TEMPLATES = {
    "MAGNET TEST": {
        "mask": "",
        "pgm_sha256": "80a01a4d7b36768bb6c3cd6ef99d91a84b5c667d7b702a3d2d6458221f5bcb82",
        "artifact": "011-exploratory-black-step-10-display-0.pgm"
    },
    "LASER KICK TEST": {
        "mask": "",
        "pgm_sha256": "bee078be42e57b635d025ddf6ee7234eb913f95bb52b20cbda1980b0b8049b14",
        "artifact": "012-exploratory-black-step-11-display-0.pgm"
    },
    "SWITCH TEST": {
        "mask": "",
        "pgm_sha256": "e61dba562c0ddec67307bcfb7d2d042102f6530fd3fad4bfc2ba1b9004b15681",
        "artifact": "013-exploratory-black-step-12-display-0.pgm"
    },
    "ACTIVE SWITCH TEST": {
        "mask": "",
        "pgm_sha256": "89a42f10a67861c47906011b53b4b960689cad63b5507c6b96bd29cb2a9fa732",
        "artifact": "014-exploratory-black-step-13-display-0.pgm"
    },
    "ALL LAMPS ON": {
        "mask": "",
        "pgm_sha256": "e56bfed5faeba33e25b4c34207a4817d72fa67f2492258e85cde4ebf21c3d178",
        "artifact": "015-exploratory-black-step-14-display-0.pgm"
    }
}
MASKS = {title: mask for title, data in TEMPLATES.items()
         if any(mask := base64.b64decode(data["mask"]))}


def match_header(frame: bytes | list[int], width: int, height: int) -> str:
    if (width, height) != (128, 32) or len(frame) != 4096:
        return ""
    header = bytes(bool(pixel) for pixel in frame[:1280])
    return next((title for title, mask in MASKS.items() if header == mask), "")


def dmd_text(recorder: harness.Recorder) -> str:
    with recorder.lock:
        matches = [
            match_header(frame, layout.get("width", 0), layout.get("height", 0))
            for index, frame in recorder.display_frames.items()
            if ((layout := recorder.display_layouts.get(index, {})).get("type", -1) & 31) == 14
        ]
    return " ".join(title for title in matches if title)


def main() -> int:
    args = harness.build_parser().parse_args()
    if args.game != "gnr_300":
        raise ValueError("Header templates are only verified for gnr_300 US 3.00")
    harness.Recorder.current_display_text = dmd_text
    return harness.main()


if __name__ == "__main__":
    sys.exit(main())
